  'Редкое': { en: 'Rare', de: 'Selten', uk: 'Рідкісне', es: 'Raro' },
  'Эпическое': { en: 'Epic', de: 'Episch', uk: 'Епічне', es: 'Épico' },
  'Легендарное': { en: 'Legendary', de: 'Legendär', uk: 'Легендарне', es: 'Legendario' },
