// Модалка кода восстановления — показываем ОДИН раз после регистрации/сброса/добавления email.
function showRecoveryModal(code, onClose) {
  const ov = document.createElement('div'); ov.className = 'modal-overlay'; ov.id = 'recovery-modal';
  ov.innerHTML = `<div class="recovery-box">
    <h3>${t('🔑 Сохрани код восстановления')}</h3>
    <p class="muted">${t('Это единственный способ вернуть доступ, если забудешь пароль. Запиши его в надёжное место — мы показываем код только сейчас.')}</p>
    <div class="recovery-code" id="recovery-code">${esc(code)}</div>
    <button class="btn ghost" id="recovery-copy">${t('📋 Скопировать')}</button>
    <button class="btn" id="recovery-ok" style="width:100%;margin-top:10px">${t('Я сохранил → продолжить')}</button>
  </div>`;
  document.body.appendChild(ov);
  ov.querySelector('#recovery-copy').addEventListener('click', () => { try { navigator.clipboard.writeText(code); toast(t('✓ Скопировано')); } catch { toast(t('Скопируй вручную')); } });
  ov.querySelector('#recovery-ok').addEventListener('click', () => { ov.remove(); if (onClose) onClose(); });
}

// Объяснение сферы: суть → что засчитывать → чем развивать. Без ИИ работает полностью;
// с ключом — можно углубиться диалогом с Тенью (определить свой стартовый уровень).
function openSphereGuide(name) {
  document.getElementById('sphguide-modal')?.remove();
  const g = sphereGuide(name);
  const ov = document.createElement('div'); ov.id = 'sphguide-modal'; ov.className = 'modal-overlay';
  const body = g
    ? `<p class="sg-what">${esc(t(g.what))}</p>
       <div class="sg-row"><b>✅ ${t('Что засчитывать')}</b><span>${esc(t(g.count))}</span></div>
       <div class="sg-row"><b>📈 ${t('Чем развивать')}</b><span>${esc(t(g.grow))}</span></div>`
    : `<p class="sg-what">${t('Это твоя сфера — значит, только ты решаешь, что в неё входит. Засчитывай любое осознанное действие в эту сторону, даже самое маленькое.')}</p>`;
  const ai = canUseAi()
    ? `<button class="btn" data-action="sphguide-ai" data-skill="${esc(name)}">🤖 ${t('Обсудить с Тенью: мой уровень здесь')}</button>`
    : `<p class="muted" style="font-size:12px;margin:8px 0 0">${t('Хочешь определить свой стартовый уровень в диалоге — добавь ключ ИИ в Настройках (есть бесплатные).')}</p>`;
  ov.innerHTML = `<div class="ai-box sg-box"><button class="modal-x" data-action="sphguide-close">✕</button>
    <h2>${esc(name)}</h2>
    ${body}
    <div class="propose-actions">${ai}</div></div>`;
  document.body.appendChild(ov);
}

// ── Онбординг v2: Тень собирает старт из пары предложений о себе ─────────────────────────
// Задача Альберта (27.07, перед раздачей приложения друзьям): «убрать порог дурака — сразу ИИ,
// сразу сферы, сразу всё нужное». Главный источник дискомфорта у новичка — не сложность, а
// паралич выбора: список из 30 чипов-сфер и пустой экран после. Здесь человек пишет о себе
// как другу — и получает готовые сферы и первые маленькие дела на сегодня.
// Ручной путь (чипы/программы) остаётся ниже: без ИИ-ключа и для тех, кто хочет сам.
let _obBusy = false, _obItems = null, _obErr = '';
function obAiBlock() {
  if (!State.aiKeys || !canUseAi()) return ''; // без ИИ — молча показываем обычный путь ниже
  if (_obItems) {
    const spheres = _obItems.filter((p) => p.type === 'sphere');
    const quests = _obItems.filter((p) => p.type === 'quest');
    const row = (p, i) => `<label class="drc-row"><input type="checkbox" data-ob-item="${i}" checked />
      <span><b>${p.type === 'sphere' ? '🧭' : '⚔️'} ${esc(p.title || p.name)}</b>${p.type === 'quest'
        ? `<br><span class="muted" style="font-size:12px">${p.day === 'tomorrow' ? t('завтра') : t('сегодня')} · ${fmtDur(Number(p.estimateMin) || 20)} · ${esc(p.sphere || '')}</span>` : ''}</span></label>`;
    return `<div class="ob-ai ob-ai-result">
      <div class="ob-section">${t('🤖 Вот что я собрал')}</div>
      <p class="muted" style="font-size:12.5px;margin:0 0 10px">${t('Сними галочки с лишнего — потом всё можно поменять.')}</p>
      <div class="dayrec-list">${_obItems.map((p, i) => row(p, i)).join('')}</div>
      <div class="ob-ai-acts">
        <button class="btn" data-action="ob-ai-apply">${t('Поехали')} (${spheres.length} ${t('сфер')} · ${quests.length} ${t('дел')})</button>
        <button class="btn ghost" data-action="ob-ai-reset">${t('Заново')}</button>
      </div></div>`;
  }
  return `<div class="ob-ai">
    <div class="ob-section">${t('🤖 Расскажи о себе — соберу всё сам')}</div>
    <p class="muted" style="font-size:12.5px;margin:0 0 8px">${t('Пара предложений своими словами: чем занимаешься, что важно, к чему идёшь. Я разложу это на сферы и первые дела.')}</p>
    <textarea id="ob-ai-text" rows="3" placeholder="${t('Например: учусь в школе, весной экзамены по био, хожу в зал 3 раза в неделю, делаю научный проект и хочу больше времени с друзьями…')}"></textarea>
    ${_obErr ? `<p class="muted" style="font-size:12px;color:var(--danger,#e0526a);margin:6px 0 0">${esc(_obErr)}</p>` : ''}
    <button class="btn" data-action="ob-ai-run" style="margin-top:10px;width:100%" ${_obBusy ? 'disabled' : ''}>${_obBusy ? t('Собираю…') : '🤖 ' + t('Собрать мой старт')}</button>
    <div class="ob-or">${t('— или выбери сам —')}</div></div>`;
}
async function obAiRun() {
  const ta = document.getElementById('ob-ai-text'), text = (ta && ta.value || '').trim();
  if (!text) { toast(t('Напиши пару слов о себе')); return; }
  if (_obBusy) return;
  _obBusy = true; _obErr = ''; renderOnboardingScreen();
  try {
    const r = await fetch('/api/ai/propose', { method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ kind: 'onboard', provider: aiProvider(), text, context: '(новый юзер, сфер пока нет)' }) });
    const d = await r.json();
    _obBusy = false;
    if (!r.ok || d.error || !Array.isArray(d.proposals)) {
      _obErr = t('Не получилось собрать — попробуй ещё раз или выбери сферы сам ниже.');
      _obItems = null; renderOnboardingScreen(); return;
    }
    const items = d.proposals.filter((p) => p && (p.name || p.title) && (p.type === 'sphere' || p.type === 'quest')).slice(0, 12);
    if (!items.filter((p) => p.type === 'sphere').length) {
      _obErr = t('Не получилось собрать — попробуй ещё раз или выбери сферы сам ниже.');
      _obItems = null; renderOnboardingScreen(); return;
    }
    _obItems = items; track('ai:onboard');
    renderOnboardingScreen();
  } catch { _obBusy = false; _obErr = t('Сетевая ошибка — попробуй ещё раз.'); _obItems = null; renderOnboardingScreen(); }
}
async function obAiApply() {
  if (!_obItems) return;
  const checks = [...document.querySelectorAll('[data-ob-item]')].map((c) => c.checked);
  const accepted = new Set(); _obItems.forEach((_, i) => { if (checks[i]) accepted.add(i); });
  if (!_obItems.some((p, i) => accepted.has(i) && p.type === 'sphere')) { toast(t('Оставь хотя бы одну сферу')); return; }
  // Стартуем с ЧИСТЫХ настроек: applyProposals пишет в State.settings.skills / State.tasks,
  // а до онбординга State ещё не инициализирован приложением. Дефолтные 6 сфер обязательно
  // затираем — иначе человек получит вперемешку свои и те, которых не выбирал.
  State.settings = structuredClone(DEFAULT_SETTINGS);
  State.settings.skills = [];
  State.tasks = []; State.goals = []; State.tree = {};
  applyProposals(_obItems, accepted);
  // saveNow, а не save: следом initApp() читает данные с сервера, и дебаунс их не догонит.
  await Store.saveNow('settings', State.settings);
  await Store.saveNow('tasks', State.tasks);
  _obItems = null; _obErr = '';
  State.phase = 'app'; initApp();
}
function renderOnboardingScreen() {
  // Ключи нужны ЗДЕСЬ, а не в initApp: до онбординга приложение не инициализировано, а без них
  // canUseAi() ложно и ИИ-блок не покажется даже тому, у кого ИИ доступен (триал/свой ключ).
  // ensureAiKeys сам дёрнет render() по приходу ответа — экран перерисуется уже с блоком.
  ensureAiKeys();
  const chips = SKILL_GROUPS.map((g) => {
    // ⚠️ не называть параметр `t` — затенит функцию перевода t() (см. баг fb_mrkzunjjmn61)
    const items = g.items.map((sk) => {
      const sel = State.obSkills.has(sk.name);
      return `<span class="ob-chip-wrap">
        <button type="button" class="ob-chip ${sel ? 'sel' : ''}" data-action="ob-toggle" data-skill="${esc(sk.name)}" data-color="${esc(sk.color)}" style="--c:${esc(sk.color)}">${sk.name}</button>
        <button type="button" class="ob-chip-q" data-action="sphere-guide" data-skill="${esc(sk.name)}" title="${t('Что это за сфера?')}" aria-label="${t('Что это за сфера?')}">?</button>
      </span>`;
    }).join('');
    return `<div class="ob-group"><div class="ob-group-h">${g.group}</div><div class="ob-group-chips">${items}</div></div>`;
  }).join('');
  document.getElementById('app').innerHTML = `
    <div class="auth-screen">
      <div class="auth-logo"><span>${esc(State.me && State.me.avatar || '⚡')}</span>
        <h1>Привет, ${esc(State.me && State.me.name || '')}!</h1>
        <p>${t('Выбери свои сферы развития — их всегда можно изменить')}</p>
      </div>
      <div class="auth-box">
        ${obAiBlock()}
        <div class="ob-section">${t('📦 Быстрый старт — готовая программа')}</div>
        <div class="prog-grid">${DUNGEON_PROGRAMS.map((p) => programCard(p, 'ob-program')).join('')}</div>
        <div class="ob-or">${t('— или собери вручную —')}</div>
        <div class="ob-groups">${chips}</div>
        <div style="margin-top:14px;display:flex;gap:8px;align-items:center">
          <input id="ob-custom" placeholder="${t('Своя сфера…')}" style="flex:1" />
          <input id="ob-color" type="color" value="#6c8cff" style="width:44px;height:38px;padding:2px;cursor:pointer" />
          <button class="btn ghost" data-action="ob-add-custom">+</button>
        </div>
        ${(() => {
          // Мягкая подсказка про пустой домен «Отношения» (§5.3) — без принуждения.
          const cov = new Set(); for (const nm of State.obSkills) { const cc = autoCanon(nm); if (cc) cov.add(cc); }
          return (State.obSkills.size > 0 && !cov.has('relations'))
            ? '<p class="ob-canon-hint">🧭 Пока нет сферы про <b>❤️ Отношения</b> — а это одна из самых весомых частей сбалансированной жизни. Можно добавить «Отношения», «Семью» или «Друзей».</p>'
            : '';
        })()}
        <button class="btn" data-action="ob-finish" style="margin-top:18px;width:100%" ${State.obSkills.size === 0 ? 'disabled' : ''}>
          Поехали! (${State.obSkills.size} сфер${State.obSkills.size === 1 ? 'а' : State.obSkills.size < 5 ? 'ы' : ''})
        </button>
      </div>
    </div>
    <div id="toasts"></div>`;
}

function showAuthScreen() {
  if (State.phase === 'login') renderLoginScreen();
  else if (State.phase === 'register') renderRegisterScreen();
  else if (State.phase === 'reset') renderResetScreen();
  else if (State.phase === 'onboarding') renderOnboardingScreen();
}

// ============================================================
//  Заголовок: персонаж
// ============================================================
function renderHeader() {
  const c = State.settings.curve, oi = levelInfo(overallXp(), c.base, c.growth), streak = currentStreak();
  const cr = charRank(), eqTitle = equippedTitle(), e = ent();
  const skills = topSkills().map((s) => {
    const si = levelInfo(skillXp(s.id), c.skillBase, c.growth), sr = rankFor(si.level), pillar = isPillar(s.id);
    const l = lang(), lvl = I18N_LVL[l] || 'ур.';
    const titleName = l === 'ru' ? s.name : i18nWord(s.name, l);
    const titleRank = l === 'ru' ? sr.name : i18nWord(sr.name, l);
    const subInfo = pillar ? ` · ${descendantSkills(s.id).length} ${l === 'ru' ? 'под-навыков' : i18nWord('под-навыков', l)}` : '';
    return `<div class="skill-chip" title="${esc(titleName)} — ${esc(titleRank)} (${lvl}${si.level}, ${skillXp(s.id)} XP)${subInfo}">
      <span class="dot" style="background:${esc(s.color)}"></span>
      <span class="sk-name">${esc(s.name)}${pillar ? ' ▾' : ''}</span><span class="sk-lvl">ур.${si.level}</span>
      <span class="sk-bar"><span style="width:${si.pct}%;background:${esc(s.color)}"></span></span></div>`;
  }).join('');
  const proBadge = e.tier === 'pro' ? `<span class="plan-badge pro" title="${t('Pro активен')}">PRO</span>`
    : e.tier === 'trial' ? `<span class="plan-badge trial" title="Pro-триал">PRO ${trialDaysLeft()}д</span>`
    : '<button class="plan-badge free" data-action="show-paywall" data-feature="Pro" title="Открыть Pro — сейчас у тебя Free">🔓 Pro?</button>';
  document.getElementById('appName').textContent = State.settings.appName || 'Satoru';
  document.getElementById('charSummary').innerHTML = `
    <div class="char-main">
      ${State.me ? `<div class="user-pill" title="${t('Профиль')}">
        <span class="up-av">${esc(State.me.avatar || '👤')}</span>
        <span class="up-meta"><span class="up-name">${esc(State.me.name)}${eqTitle ? ` <span class="eq-title">🏷 ${esc(eqTitle)}</span>` : ''}</span>
        <span class="up-rank" style="--rc:${cr.color}">${cr.icon} ${cr.name}</span></span></div>` : ''}
      <div class="char-level">Уровень <b>${oi.level}</b></div>
      <div class="xp-bar"><span style="width:${oi.pct}%"></span><i>${oi.into} / ${oi.need} XP</i></div>
      <div class="gold-pill" title="Золото">🪙 ${goldBalance()}</div>
      <div class="streak" title="${t('Рекорд:')} ${longestStreak()} ${plural(longestStreak(), 'день', 'дня', 'дней')}">🔥 ${streak} ${plural(streak, 'день', 'дня', 'дней')}</div>
      ${hypePct() > 0 ? `<div class="hype-chip" title="Хайп ×${hypeState().stacks}: бонус XP за добровольный выбор сложных квестов. Осталось ${hypeMinLeft()} мин.">🔥 Хайп +${hypePct()}%</div>` : ''}
      <button class="help-btn" data-action="show-guide" title="${t('Как играть')}">?</button>
      ${proBadge}
      <button class="btn ghost logout-btn" data-action="logout" title="${t('Сменить профиль')}">${t('⇦ Выйти')}</button>
    </div>
    <div class="skills-row">${skills}</div>`;
}

// ============================================================
//  Вид «Сегодня»
// ============================================================
function catChips(t) {
  const ids = taskSkills(t);
  if (!ids.length) return `<span class="t-cat missing">— сфера —</span>`;
  return ids.map((sid) => { const s = skillById(sid); return `<span class="t-cat ${s.missing ? 'missing' : ''}" style="--c:${esc(s.color)}">${esc(s.name)}</span>`; }).join('');
}
// ⚠️ Параметр НЕ называть `t` — затенил бы глобальную функцию перевода t() (см. баг fb_mrkzunjjmn61).
function questRow(q) {
  const estMin = Number(q.estimateMin) || 0;
  const time = q.actualMin ? `${fmtDur(q.actualMin)} / ${fmtDur(estMin)}` : fmtDur(estMin);
  const active = State.timer && State.timer.taskId === q.id;
  const skSel = `<button class="t-cats" data-action="edit-cats" data-id="${q.id}" title="Категории квеста — клик чтобы изменить (можно несколько)">${catChips(q)}</button>`;
  const titleCell = State._editTask === q.id
    ? `<form class="t-edit-form" data-id="${q.id}"><input name="title" value="${esc(q.title)}" maxlength="120" autocomplete="off" /></form>`
    : `<span class="t-title" data-action="edit-task-title" data-id="${q.id}" title="Клик — изменить текст квеста">${esc(q.title)}</span>`;
  // Квест из прошлого: «✓ в свой день» — засчитать в дату плана, а не в сегодня (fb_mr4qhq6gy30w)
  const past = !q.done && q.date && q.date < todayStr();
  const backdate = past
    ? `<button class="t-backdate" data-action="toggle-task-backdated" data-id="${q.id}" title="${t('Сделал в тот день, забыл отметить — засчитать в')} ${dmShort(q.date)}">✓<sub>${dmShort(q.date)}</sub></button>`
    : '';
  return `<li class="task ${q.done ? 'done' : ''}">
    <button class="check" data-action="toggle-task" data-id="${q.id}">${q.done ? '✓' : ''}</button>
    ${titleCell}
    ${skSel}
    <span class="t-time" data-action="edit-actual" data-id="${q.id}" title="Клик — фактическое время">${time}</span>
    <span class="t-diff">${DIFF[q.difficulty] || ''}</span>
    <span class="t-xp">${q.done ? (q.entry ? '💛' : '+' + (q.xpAwarded || 0)) : ''}</span>
    ${q.done ? '<span></span>' : `<button class="focus ${active ? 'active' : ''}" data-action="focus-task" data-id="${q.id}" title="Фокус-таймер">${active ? '⏱' : '▶'}</button>`}
    ${backdate}
    ${q.oath && !q.done ? `<span class="t-oath" title="Клятва Кремню: заверши сегодня или −${q.oath.gold} 🪙">⚔️${q.oath.gold}</span>` : (!q.done && currentPath() === 'control' && q.date === todayStr() && goldBalance() >= CONTROL.oathGold ? `<button class="t-oath-btn" data-action="quest-oath" data-id="${q.id}" title="Клятва Кремню: заверши до конца дня — золото за квест ×1.5; провали — сгорит ${CONTROL.oathGold} 🪙">⚔️</button>` : '')}
    <button class="del" data-action="delete-task" data-id="${q.id}" title="Удалить">✕</button></li>`;
}
function habitRow(h) {
  const sk = skillById(h.skillId), done = habitDone(h, todayStr()), hs = habitStreak(h);
  return `<li class="task habit ${done ? 'done' : ''}">
    <button class="check" data-action="toggle-habit" data-id="${h.id}">${done ? '✓' : ''}</button>
    <span class="t-title">${esc(h.title)}</span>
    <span class="t-skill" style="--c:${esc(sk.color)}">${esc(sk.name)}</span>
    <span class="t-time">${fmtDur(h.estimateMin)}</span>
    <span class="t-diff">${DIFF[h.difficulty] || ''}</span>
    <span class="t-xp">${done ? '+' + itemXp(h) : ''}</span>
    <span class="habit-streak" title="Серия">${hs ? '🔥' + hs : ''}</span><span></span></li>`;
}
// ============================================================
//  Вид «Календарь» — день по часам (Apple-стиль), отдельная вкладка
// ============================================================
const CAL_H0 = 6, CAL_H1 = 23, CAL_ROWH = 48;
function calMinToY(min) { return (min - CAL_H0 * 60) / 60 * CAL_ROWH; }
function calYtoMin(y) { const raw = CAL_H0 * 60 + y / CAL_ROWH * 60; return Math.max(CAL_H0 * 60, Math.min(CAL_H1 * 60 + 45, Math.round(raw / 15) * 15)); }
function fmtHM(min) { return pad2(Math.floor(min / 60)) + ':' + pad2(min % 60); }
const MONTHS_NOM = ['Январь', 'Февраль', 'Март', 'Апрель', 'Май', 'Июнь', 'Июль', 'Август', 'Сентябрь', 'Октябрь', 'Ноябрь', 'Декабрь'];
function calModeToggle(mode) {
  return `<div class="cal-modes">
    <button class="cal-mode ${mode === 'day' ? 'active' : ''}" data-action="cal-mode" data-mode="day">День</button>
    <button class="cal-mode ${mode === 'week' ? 'active' : ''}" data-action="cal-mode" data-mode="week">Неделя</button>
    <button class="cal-mode ${mode === 'month' ? 'active' : ''}" data-action="cal-mode" data-mode="month">Месяц</button></div>`;
}
function calRemindBtn() {
  const on = State.settings && State.settings.remind;
  return `<button class="btn ghost sm cal-remind ${on ? 'on' : ''}" data-action="cal-remind-toggle" title="Напоминания о задачах со временем (пока вкладка открыта)">${on ? '🔔 Напоминания вкл' : '🔕 Напоминания'}</button>`;
}
function calExportBtn() { return `<button class="btn ghost sm" data-action="export-ics" title="Скачать запланированные квесты как .ics — импортировать в Apple/Google Календарь (разово; #8)">📆 .ics</button>`; }
function calSubscribeBtn() { return `<button class="btn ghost sm" data-action="show-cal-subscribe" title="Живая подписка на квесты в Apple/Google Календарь">${t('📅 Подписка')}</button>`; }

async function showCalSubscribeModal() {
  if (document.getElementById('cal-sub-ov')) return;
  const ov = document.createElement('div');
  ov.id = 'cal-sub-ov'; ov.className = 'modal-overlay';
  ov.innerHTML = `<div class="guide-box"><button class="modal-x" data-action="close-cal-subscribe">✕</button>
    <h2>${t('Живая подписка на квесты')}</h2>
    <p class="muted" style="font-size:13px">Квесты автоматически обновляются в Apple/Google Календаре при добавлении новых.</p>
    <div id="cal-sub-body" style="margin-top:12px"><span class="muted">Генерация ссылки…</span></div>
  </div>`;
  document.body.appendChild(ov);
  try {
    const r = await fetch('/api/auth/cal-secret', { method: 'POST' });
    const d = await r.json();
    const base = location.origin + '/api/cal/' + d.userId + '/' + d.secret;
    const webcal = 'webcal://' + base.replace(/^https?:\/\//, '');
    document.getElementById('cal-sub-body').innerHTML = `
      <label style="display:block;font-size:12px;color:var(--muted);margin-bottom:4px">${t('Ссылка для подписки')}</label>
      <div style="display:flex;gap:6px;margin-bottom:14px">
        <input id="cal-sub-url" readonly value="${esc(base)}" style="flex:1;font-size:12px;padding:6px 10px;border-radius:8px;border:1.5px solid var(--line);background:var(--panel2);color:var(--fg)"/>
        <button class="btn ghost sm" data-action="copy-cal-url" data-url="${esc(base)}">Копировать</button>
      </div>
      <a class="btn sm" href="${esc(webcal)}" style="display:inline-block;margin-bottom:16px">📲 ${t('Открыть в Календаре')}</a>
      <p class="muted" style="font-size:12px;line-height:1.5">
        <b>Apple Календарь (iOS):</b> Настройки → Учётные записи → Добавить → Другая → Подписной календарь → вставь ссылку.<br>
        <b>Apple Календарь (Mac):</b> Файл → Новый подписной календарь → вставь ссылку.<br>
        <b>Google Календарь:</b> Другие календари → + → По URL → вставь ссылку.
      </p>`;
  } catch {
    document.getElementById('cal-sub-body').innerHTML = `<span class="muted">Ошибка, попробуй ещё раз</span>`;
  }
}
// Экспорт запланированных квестов (с датой и временем) в iCalendar (#8). Разовый экспорт, не живая подписка.
function buildICS() {
  const tasks = (State.tasks || []).filter((t) => t.date && t.startTime);
  const stamp = new Date().toISOString().replace(/[-:]/g, '').split('.')[0] + 'Z';
  const escV = (s) => String(s || '').replace(/([,;\\])/g, '\\$1').replace(/\n/g, '\\n');
  const dt = (date, time) => `${date.replace(/-/g, '')}T${(time || '09:00').replace(':', '')}00`;
  const lines = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Satoru//Life Planner//RU', 'CALSCALE:GREGORIAN', 'METHOD:PUBLISH', 'X-WR-CALNAME:Satoru'];
  tasks.forEach((t) => {
    const dur = Math.max(5, Number(t.estimateMin) || 30);
    lines.push('BEGIN:VEVENT', `UID:${t.id}@gojo`, `DTSTAMP:${stamp}`, `DTSTART:${dt(t.date, t.startTime)}`, `DURATION:PT${dur}M`,
      `SUMMARY:${escV('🎯 ' + t.title)}`, `DESCRIPTION:${escV('Satoru · ' + (skillById(t.skillId).name || ''))}`, 'END:VEVENT');
  });
  lines.push('END:VCALENDAR');
  return lines.join('\r\n');
}
// Месячная сетка (6×7, с понедельника). Клик по дню → день этой даты.
function renderCalMonth(date) {
  const WD = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];
  const d = parseDate(date), y = d.getFullYear(), mo = d.getMonth();
  const first = new Date(y, mo, 1), startJs = first.getDay();
  const gridStart = addDays(fmtDate(first), -((startJs === 0 ? 7 : startJs) - 1)); // понедельник перед 1-м
  const counts = {};
  for (const t of State.tasks) if (!t.done) counts[t.date] = (counts[t.date] || 0) + 1;
  let cells = '';
  for (let i = 0; i < 42; i++) {
    const ds = addDays(gridStart, i), cd = parseDate(ds), inMonth = cd.getMonth() === mo;
    const n = counts[ds] || 0, isToday = ds === todayStr(), isSel = ds === date;
    cells += `<button class="cm-cell ${inMonth ? '' : 'cm-out'} ${isToday ? 'cm-today' : ''} ${isSel ? 'cm-sel' : ''}" data-action="cal-pick-day" data-date="${ds}">
      <span class="cm-n">${cd.getDate()}</span>${n ? `<span class="cm-dot">${n > 9 ? '9+' : n}</span>` : ''}</button>`;
  }
  return `
    <div class="card calv-head">
      <div class="calv-title">
        <button class="btn ghost sm" data-action="cal-shift-month" data-delta="-1" title="Предыдущий месяц">‹</button>
        <h2>${MONTHS_NOM[mo]} ${y}</h2>
        <button class="btn ghost sm" data-action="cal-shift-month" data-delta="1" title="Следующий месяц">›</button>
        ${calModeToggle('month')}<div class="cal-tools">${calExportBtn()}${calSubscribeBtn()}${calRemindBtn()}</div>
      </div>
      <div class="cm-wd">${WD.map((w) => `<span>${w}</span>`).join('')}</div>
      <div class="cm-grid">${cells}</div>
    </div>`;
}
function renderCalendarView() {
  const date = State.calDate || (State.calDate = todayStr());
  if ((State.calMode || 'day') === 'month') return renderCalMonth(date);
  if (State.calMode === 'week') { if (!State.weekStart) State.weekStart = weekStart(todayStr()); return renderWeekly(); }
  const WD = ['Вс', 'Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб'];
  const MON = ['января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'];
  const d = parseDate(date);
  const dayTasks = (State.tasks || []).filter((t) => t.date === date);
  const scheduled = dayTasks.filter((t) => t.startTime);
  const unscheduled = dayTasks.filter((t) => !t.startTime && !t.done);
  // полоса недели вокруг выбранной даты (с понедельника)
  const js = d.getDay(), mon = addDays(date, -(js === 0 ? 6 : js - 1));
  let strip = '';
  for (let i = 0; i < 7; i++) {
    const ds = addDays(mon, i), open = State.tasks.filter((t) => t.date === ds && !t.done).length;
    strip += `<button class="calv-day ${ds === date ? 'active' : ''} ${ds === todayStr() ? 'is-today' : ''}" data-action="cal-date" data-date="${ds}">
      <span class="cd-wd">${WD[parseDate(ds).getDay()]}</span><span class="cd-n">${Number(ds.slice(8))}</span>${open ? `<span class="cd-dot">${open}</span>` : '<span class="cd-dot-empty"></span>'}</button>`;
  }
  const hours = [];
  for (let h = CAL_H0; h <= CAL_H1; h++) hours.push(h);
  const grid = hours.map((h, i) => `<div class="cal-row" style="top:${i * CAL_ROWH}px"><span class="cal-h">${pad2(h)}:00</span></div>`).join('');
  const nowMin = (() => { const n = new Date(); return n.getHours() * 60 + n.getMinutes(); })();
  const nowLine = (date === todayStr() && nowMin >= CAL_H0 * 60 && nowMin <= (CAL_H1 + 1) * 60) ? `<div class="calv-now" style="top:${calMinToY(nowMin)}px"></div>` : '';
  const blocks = scheduled.map((t) => {
    const [H, M] = t.startTime.split(':').map(Number);
    const dur = Number(t.estimateMin) || 30;
    const sk = skillById(t.skillId);
    return `<div class="cal-block calv-block ${t.done ? 'done' : ''}" draggable="true" data-id="${t.id}" style="top:${calMinToY(H * 60 + M)}px;height:${Math.max(24, dur / 60 * CAL_ROWH)}px;--c:${esc(sk.color)}" title="${esc(t.title)} · ${fmtDur(dur)} — тяни, чтобы перенести">
      <button class="check sm cal-check" data-action="toggle-task" data-id="${t.id}">${t.done ? '✓' : ''}</button>
      <span class="cal-b-text"><b>${pad2(H)}:${pad2(M)}</b> ${esc(t.title)}<span class="cal-dur"> · ${fmtDur(dur)}</span></span>
      <button class="cal-x" data-action="unschedule-quest" data-id="${t.id}" title="Снять с расписания">✕</button></div>`;
  }).join('');
  const trayTasks = unscheduled.map((t) => { const sk = skillById(t.skillId); return `<span class="calv-chip" draggable="true" data-id="${t.id}" style="--c:${esc(sk.color)}" title="Тяни в сетку, чтобы поставить на время">⠿ ${esc(t.title)} <span class="muted">${fmtDur(Number(t.estimateMin) || 30)}</span><button class="calv-chip-del" data-action="delete-task" data-id="${t.id}" title="Удалить квест">✕</button></span>`; }).join('');
  const dur0 = unscheduled.length ? (Number(unscheduled[0].estimateMin) || 30) : 30;
  const picker = unscheduled.length ? `
    <div class="cal-schedule">
      <select id="cal-quest">${unscheduled.map((t) => `<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select>
      <input id="cal-time" type="time" value="09:00" title="Начало" />
      <input id="cal-dur" type="number" min="1" step="1" value="${dur0}" title="Длительность, мин (любое число — не только кратное 5)" />
      <span class="cal-dur-unit muted">мин</span>
      <button class="btn ghost" data-action="schedule-quest">🗓 Поставить</button>
    </div>` : '';
  const planned = dayTasks.reduce((s, t) => s + (Number(t.estimateMin) || 0), 0);
  return `
    <div class="card calv-head">
      <div class="calv-title">
        <button class="btn ghost sm" data-action="cal-shift" data-days="-1" title="Предыдущий день">‹</button>
        <h2>${d.getDate()} ${MON[d.getMonth()]} <span class="muted">· ${WD[d.getDay()]}${date === todayStr() ? ' · сегодня' : ''}</span></h2>
        <button class="btn ghost sm" data-action="cal-shift" data-days="1" title="Следующий день">›</button>
        ${date !== todayStr() ? '<button class="btn ghost sm" data-action="cal-today">Сегодня</button>' : ''}
        <span class="wk-load muted">план: ${fmtDur(planned)}</span>
        ${calModeToggle('day')}<div class="cal-tools">${calExportBtn()}${calSubscribeBtn()}${calRemindBtn()}</div>
      </div>
      <div class="calv-strip">${strip}</div>
    </div>
    <div class="card">
      <form id="add-task" class="add-row">
        <input type="hidden" name="date" value="${date}" />
        <input name="title" placeholder="Новый квест на этот день…" autocomplete="off" required />
        <select name="skillId">${skillOptionsHTML()}</select>
        ${durInputHTML('estimateMin', 30)}
        <select name="difficulty"><option value="easy">🌱 Лёгкая</option><option value="normal" selected>⚔️ Обычная</option><option value="hard">🔥 Сложная</option></select>
        <button type="submit">+ Квест</button></form>
    </div>
    ${unscheduled.length ? `<div class="card calv-tray"><h3>📥 Без времени (${unscheduled.length})</h3><div class="calv-chips">${trayTasks}</div>${picker}</div>` : ''}
    <div class="card">
      <p class="cal-hint muted">Тяни квест по сетке, чтобы сменить время (шаг 15 мин). Клик по пустому месту — подставить время в форму. Крестик ✕ — снять с расписания.</p>
      <div class="cal calv-grid" style="height:${hours.length * CAL_ROWH}px">${grid}${nowLine}${blocks}</div>
    </div>`;
}
// ============================================================
//  Быстрый захват + Инбокс (Блок 2) — текст/голос/видео, замена Telegram «Избранное»
// ============================================================
let _rec = null; // { kind, recorder, chunks, stream, startedAt, timer }
let _mobilSnoozeDay = null; // «Позже» для нуджа мобилки — на сегодня
// Профилактика травм: за 7 дней были силовые/единоборства, но НЕ было мобилки/растяжки?
function trainingWithoutMobility() {
  const since = addDays(todayStr(), -7);
  const strengthRe = /зал|штанг|жим|силов|присед|становая|тяга|дзюдо|единоборств|бокс|борьб|gym|judo/i;
  const mobilityRe = /растяжк|мобил|йог|разминк|гибкост|шпагат|суставн|stretch|mobility/i;
  let strength = false, mobility = false;
  for (const t of State.tasks) if (t.done && dayOf(t) >= since) { const n = normRu(t.title); if (strengthRe.test(n)) strength = true; if (mobilityRe.test(n)) mobility = true; }
  for (const d in State.habitlog) if (d >= since) for (const hid in State.habitlog[d]) { const h = habitById(hid); if (h) { const n = normRu(h.title); if (strengthRe.test(n)) strength = true; if (mobilityRe.test(n)) mobility = true; } }
  return strength && !mobility;
}

// ---- Анти-привычки (Блок 4): «чистые дни», без стыда. Срыв = данные, не провал. ----
function antiDates(a) { return (a.slips || []).slice().sort(); }
function antiLastSlip(a) { const s = antiDates(a); return s.length ? s[s.length - 1] : null; }
function antiCleanDays(a) {
  const last = antiLastSlip(a), from = last || (a.createdAt ? fmtDate(new Date(a.createdAt)) : todayStr());
  return Math.max(0, Math.round((parseDate(todayStr()) - parseDate(from)) / 86400000));
}
function antiBestStreak(a) {
  const start = a.createdAt ? fmtDate(new Date(a.createdAt)) : todayStr();
  const pts = [start, ...antiDates(a), todayStr()];
  let best = 0; for (let i = 1; i < pts.length; i++) { const gap = Math.round((parseDate(pts[i]) - parseDate(pts[i - 1])) / 86400000); if (gap > best) best = gap; }
  return best;
}
function antiHabitsCard() {
  const list = State.antihabits || []; if (!list.length) return '';
  const rows = list.map((a) => {
    const clean = antiCleanDays(a), best = antiBestStreak(a), slippedToday = antiLastSlip(a) === todayStr();
    return `<div class="anti-row">
      <div class="anti-main"><span class="anti-title">${esc(a.title)}</span>
        <span class="anti-stat">🟢 <b>${clean}</b> ${plural(clean, 'день', 'дня', 'дней')} чисто${best > clean ? ` · рекорд ${best}` : ''}</span></div>
      ${slippedToday
        ? `<button class="btn ghost sm anti-undo" data-action="anti-unslip" data-id="${a.id}">сегодня был срыв · отменить</button>`
        : `<button class="btn ghost sm" data-action="anti-slip" data-id="${a.id}">был срыв?</button>`}</div>`;
  }).join('');
  return `<div class="card anti-card"><h3>🛡 Свобода от привычек</h3>${rows}
    <p class="muted anti-note">Срыв — не провал, а данные. Без стыда: это копинг, а не ты. Заметь, что его вызвало — и иди дальше. Завтра новый чистый день 🌱</p></div>`;
}

// ============================================================
