    _dayActs = (d.proposals || []).filter((p) => p && p.title).map((p) => ({ title: String(p.title).slice(0, 120), sphere: String(p.sphere || ''), minutes: Math.max(1, Math.round(Number(p.minutes) || 15)), time: String(p.time || '') }));
