const ACCENTS = ['#6c8cff', '#22c1a4', '#e0526a', '#b06ff0', '#e0a23e', '#4f9ff7']; // палитра акцентов (#тема)
function applyTheme() {
  const s = State.settings || {};
  // Путь «Контроль» авто-надевает скин «Система» (Solo-Leveling-эстетика строгости), если юзер явно не отключил его оверрайдом.
  const controlSkin = s.path === 'control' && !s.systemSkinOff;
  const sys = !!s.systemMode || controlSkin;
  document.documentElement.dataset.theme = sys ? 'dark' : (s.theme === 'light' ? 'light' : 'dark');
  document.documentElement.dataset.system = sys ? 'on' : 'off';
  document.documentElement.dataset.path = s.path === 'control' ? 'control' : 'trust';
  document.documentElement.style.setProperty('--accent', sys ? '#4fd6ff' : (s.accent || '#6c8cff'));
}
// Авто-репорт креша на сервер (раз на ключ за сессию) — чтобы видеть прод-падения в фидбеке.
function reportCrash(view, e) {
  try {
    State._reportedErrors = State._reportedErrors || new Set();
    const key = view + ':' + ((e && e.message) || e);
    if (State._reportedErrors.has(key)) return; State._reportedErrors.add(key);
    fetch('/api/feedback', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ kind: 'bug', text: `[авто-креш] раздел «${view}»: ` + String((e && e.stack) || e).slice(0, 900), attachments: [] }) }).catch(() => {});
  } catch {}
}
function viewErrorCard(view, e) {
  const admin = State.me && State.me.isAdmin;
  return `<div class="card err-card">
    <h3>😔 Этот раздел не открылся</h3>
    <p class="muted">Сбой в разделе «${esc(view)}», но твои данные целы. Вернись на «Сегодня» или обнови страницу — отчёт уже ушёл нам.</p>
    <div class="err-acts"><button class="btn" data-action="goto-today">← На сегодня</button><button class="btn ghost" data-action="reload-app">↻ Обновить</button></div>
    ${admin ? `<pre class="err-trace">${esc(String((e && e.stack) || e)).slice(0, 700)}</pre>` : ''}
  </div>`;
}
// Гарантирует, что core-поля состояния — нужного типа (массив/объект), а не null/мусор.
// Корневая защита от краша вида (Календарь/Статистика у Виолы): любой хелпер итерирует безопасно.
function normalizeCoreState() {
  for (const k of ['tasks', 'habits', 'goals', 'purchases', 'rewards', 'inbox', 'antihabits']) if (!Array.isArray(State[k])) State[k] = [];
  for (const k of ['days', 'habitlog', 'tree', 'achievements', 'weeks']) if (!State[k] || typeof State[k] !== 'object' || Array.isArray(State[k])) State[k] = {};
}
function render() {
  if (State.phase !== 'app') { showAuthScreen(); return; }
  try { normalizeCoreState(); } catch (e) { console.error('normalizeCoreState', e); }
  try { applyTheme(); } catch (e) { console.error('applyTheme', e); }
  try { pathReckoning(); } catch (e) { /* расчёт Контроля — не критично для рендера */ }
  // Восстановить app shell если auth-экран его перезаписал
  if (!document.getElementById('main')) document.getElementById('app').innerHTML = APP_SHELL;
  // Тень не должна продолжать говорить в другом разделе. Внутри одного вида перерисовка
  // (тик таймера и т.п.) речь НЕ прерывает — иначе фраза рубилась бы на полуслове.
  if (_ttsBtn && _ttsView !== State.view) ttsStop();
  try { renderHeader(); } catch (e) { console.error('renderHeader', e); }
  try { renderNav(); } catch (e) { console.error('renderNav', e); }
  const main = document.getElementById('main');
  try {
    main.innerHTML = (VIEWS[State.view] || renderToday)();
  } catch (e) {
    // Error-boundary: сбой одного раздела не должен белить весь экран
    console.error('Сбой рендера раздела:', State.view, e);
    reportCrash(State.view, e);
    try { main.innerHTML = viewErrorCard(State.view, e); } catch { main.innerHTML = '<div class="card"><p>Ошибка. Обнови страницу.</p></div>'; }
  }
  try { if (lang() !== 'ru') translateDOM(document.body); } catch (e) { console.error('translateDOM', e); }
  try { scheduleReminders(); } catch (e) { console.error('scheduleReminders', e); }
  try { kickCompVideo(); } catch (e) { /* видео-автоплей — не критично */ }
  try { tutorialPaint(); } catch (e) { /* гайд-оверлей — не критично */ }
  try { dripCheck(); } catch (e) { /* капельница гайда — не критично */ }
  try { momentCheck(); } catch (e) { /* момент дня — тоже не критично для рендера */ }
  // Стрик прямо на кнопке Тени: маленькая цифра вместо отдельной карточки на экране
  try {
    const fs = document.getElementById('fab-streak'), st = currentStreak();
    if (fs) { if (st > 0) { fs.textContent = '🔥' + st; fs.hidden = false; } else fs.hidden = true; }
  } catch {}
  dismissBootLoader();
}
function dismissBootLoader() {
  const loader = document.getElementById('satoru-boot');
  if (!loader || loader.dataset.dismissed) return;
  loader.dataset.dismissed = '1';
  requestAnimationFrame(() => loader.classList.add('is-done'));
  setTimeout(() => loader.remove(), 420);
}
// iOS: атрибут `muted` из innerHTML не всегда регистрируется и блокирует autoplay.
// Принудительно мьютим и стартуем; если play() отклонён — остаётся poster (персонаж виден).
function kickCompVideo() {
  document.querySelectorAll('video.comp-video').forEach((v) => {
    v.muted = true; v.defaultMuted = true;
    const p = v.play();
    if (p && p.catch) p.catch(() => {});
  });
}

// ============================================================
//  События
// ============================================================
function onSubmit(e) {
  const f = e.target;

  // --- Компаньон: чек-ин (утро/вечер) ---
  if (f.id === 'comp-checkin') {
    e.preventDefault();
    const c = ensureCompanion(), t = todayStr(), kind = f.dataset.kind === 'e' ? 'e' : 'm';
    const text = (f.text.value || '').trim().slice(0, 200);
    c.check[t] = Object.assign({}, c.check[t], { [kind]: true });
    if (text) { c.journal.push({ date: t, kind, text }); if (c.journal.length > 120) c.journal = c.journal.slice(-120); }
    c.bond += 2 + Math.round((globalPerk('bond') || 0) / 6); // 💜 перк древа усиливает связь за чек-ин
    c.lastSeen = t; State._compAway = 0; State._compForm = null;
    Store.save('settings', State.settings);
    if (typeof sfx === 'function') sfx('complete');
    toast(kind === 'm' ? '🌅 Утро отмечено вместе' : '🌙 Хорошего тебе вечера 💛');
    render(); return;
  }
  // --- Компаньон: переименование ---
  if (f.id === 'comp-rename') {
    e.preventDefault();
    const c = ensureCompanion(); c.name = (f.name.value || '').trim().slice(0, 24) || 'Тень';
    State._compForm = null; Store.save('settings', State.settings); toast('✨ Имя сохранено'); render(); return;
  }
  // --- Квест: правка текста ---
  if (f.classList && f.classList.contains('t-edit-form')) {
    e.preventDefault();
    const t = questById(f.dataset.id);
    if (t) { const v = (f.title.value || '').trim().slice(0, 120); if (v) t.title = v; Store.save('tasks', State.tasks); }
    State._editTask = null; render(); return;
  }
  // --- Питомец: переименование ---
  if (f.classList && f.classList.contains('pet-rename-form')) {
    e.preventDefault();
    const id = f.dataset.id, nm = (f.name.value || '').trim().slice(0, 20);
    State.settings.petNames = State.settings.petNames || {};
    if (nm && nm !== skillById(id).name) State.settings.petNames[id] = nm; else delete State.settings.petNames[id];
    State._petRename = null; Store.save('settings', State.settings); toast('✨ Имя питомца сохранено'); render(); return;
  }

  // --- PIN login ---
  if (f.id === 'pin-form') {
    e.preventDefault();
    const userId = f.dataset.id, pin = f.pin.value;
    const errEl = f.querySelector('#pin-error');
    fetch('/api/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ userId, pin }) })
      .then(async r => { const d = await r.json(); if (r.ok) { State.me = d; initApp(); } else { if (errEl) errEl.textContent = d.error || 'Неверный PIN'; f.pin.value = ''; } })
      .catch(() => { if (errEl) errEl.textContent = 'Ошибка сети'; });
    return;
  }

  // --- Login (email+пароль) ---
  if (f.id === 'login-form') {
    e.preventDefault();
    const errEl = f.querySelector('#login-error');
    fetch('/api/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email: f.email.value.trim(), password: f.password.value }) })
      .then(async r => { const d = await r.json(); if (r.ok) { State.me = d; initApp(); } else { errEl.textContent = d.error || 'Не удалось войти'; f.password.value = ''; } })
      .catch(() => { errEl.textContent = 'Ошибка сети'; });
    return;
  }

  // --- Register (email+пароль) ---
  if (f.id === 'register-form') {
    e.preventDefault();
    const name = f.name.value.trim(), email = f.email.value.trim(), pw = f.password.value, pw2 = f.password2.value;
    const errEl = f.querySelector('#reg-error');
    if (pw !== pw2) { errEl.textContent = 'Пароли не совпадают'; return; }
    if (pw.length < 6) { errEl.textContent = 'Пароль минимум 6 символов'; return; }
    fetch('/api/auth/register', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name, email, password: pw, avatar: State.regAvatar || '⚡' }) })
      .then(async r => {
        const d = await r.json();
        if (r.ok) { State.me = d; State.phase = 'onboarding'; render(); if (d.recoveryCode) showRecoveryModal(d.recoveryCode); }
        else { errEl.textContent = d.error || 'Ошибка регистрации'; }
      })
      .catch(() => { f.querySelector('#reg-error').textContent = 'Ошибка сети'; });
    return;
  }

  // --- Reset (по коду восстановления) ---
  if (f.id === 'reset-form') {
    e.preventDefault();
    const errEl = f.querySelector('#reset-error');
    fetch('/api/auth/reset', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email: f.email.value.trim(), code: f.code.value.trim(), newPassword: f.newPassword.value }) })
      .then(async r => {
        const d = await r.json();
        if (r.ok) { State.me = d; const code = d.recoveryCode; initApp(); if (code) showRecoveryModal(code); }
        else { errEl.textContent = d.error || 'Не удалось сбросить'; }
      })
      .catch(() => { errEl.textContent = 'Ошибка сети'; });
    return;
  }

  // --- Привязать email+пароль к существующему аккаунту ---
  if (f.id === 'add-email') {
    e.preventDefault();
    const msg = f.querySelector('#add-email-msg');
    fetch('/api/auth/add-email', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email: f.email.value.trim(), password: f.password.value }) })
      .then(async (r) => {
        const d = await r.json();
        if (r.ok) { if (State.me) State.me.email = d.email; msg.textContent = '✓ Привязано'; if (d.recoveryCode) showRecoveryModal(d.recoveryCode, () => render()); }
        else { msg.textContent = d.error || 'Ошибка'; msg.style.color = '#e0526a'; }
      })
      .catch(() => { msg.textContent = 'Ошибка сети'; msg.style.color = '#e0526a'; });
    return;
  }

  // --- Удаление аккаунта ---
  if (f.id === 'del-account-form') {
    e.preventDefault();
    const msg = f.querySelector('#del-account-msg');
    const btn = f.querySelector('button[type="submit"]');
    msg.textContent = 'Удаляю…'; msg.style.color = 'var(--muted)';
    btn.disabled = true;
    const body = {};
    if (f.password) body.password = f.password.value;
    if (f.pin) body.pin = f.pin.value;
    fetch('/api/auth/delete-account', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
      .then(async (r) => {
        const d = await r.json();
        if (r.ok) {
          document.getElementById('del-account-modal')?.remove();
          State.me = null; State.phase = 'login'; stopFocus(false); clearAllData();
          fetch('/api/auth/profiles').then(r2 => r2.json()).then(p => { State.profiles = p; render(); }).catch(() => { State.profiles = []; render(); });
        } else {
          msg.textContent = d.error || 'Ошибка'; msg.style.color = 'var(--bad)'; btn.disabled = false;
        }
      })
      .catch(() => { msg.textContent = 'Ошибка сети'; msg.style.color = 'var(--bad)'; btn.disabled = false; });
    return;
  }

  // --- Смена PIN ---
  if (f.id === 'change-pin') {
    e.preventDefault();
    const msg = f.querySelector('#pin-change-msg');
    fetch('/api/auth/change-pin', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ oldPin: f.oldPin.value, newPin: f.newPin.value }) })
      .then(async (r) => { const d = await r.json(); if (r.ok) { msg.textContent = '✓ PIN изменён'; msg.style.color = '#5fbf7a'; f.reset(); } else { msg.textContent = d.error || 'Ошибка'; msg.style.color = '#e0526a'; } })
      .catch(() => { msg.textContent = 'Ошибка сети'; msg.style.color = '#e0526a'; });
    return;
  }

  // --- Админ: выдать Pro ---
  if (f.id === 'grant-pro') {
    e.preventDefault();
    const msg = f.querySelector('#grant-msg'), days = f.days.value ? Number(f.days.value) : undefined;
    fetch('/api/auth/grant-pro', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ userId: f.userId.value.trim(), days }) })
      .then(async (r) => { const d = await r.json(); if (r.ok) { msg.textContent = `✓ Pro выдан: ${d.name}`; msg.style.color = '#5fbf7a'; if (d.id === (State.me && State.me.id)) { State.me = d; render(); } } else { msg.textContent = d.error || 'Ошибка'; msg.style.color = '#e0526a'; } })
      .catch(() => { msg.textContent = 'Ошибка сети'; msg.style.color = '#e0526a'; });
    return;
  }
  if (f.id === 'recover-data') {
    e.preventDefault();
    const uid = f.userId.value.trim(); if (uid) showUserData(uid);
    return;
  }

  // --- Обратная связь ---
  if (f.id === 'feedback-form') {
    e.preventDefault();
    const msg = f.querySelector('#fb-msg'), btn = f.querySelector('button[type="submit"]');
    const files = [...(f.files.files || [])];
    if (!f.text.value.trim() && !files.length) { msg.textContent = 'Опиши или приложи файл'; msg.style.color = '#e0526a'; return; }
    btn.disabled = true; msg.style.color = 'var(--muted)'; msg.textContent = files.length ? 'Обрабатываю файлы…' : 'Отправляю…';
    (async () => {
      let attachments = [];
      try { attachments = await Promise.all(files.map(readAttachment)); }
      catch (err) { msg.textContent = err.message || 'Файл не подошёл'; msg.style.color = '#e0526a'; btn.disabled = false; return; }
      // Суммарный чек ДО отправки: один файл может пройти лимит (25 МБ), но несколько сразу — уже нет.
      // Без этого юзер получал бы невнятную серверную "bad json" вместо понятной причины.
      const totalB64 = attachments.reduce((s, a) => s + (a.dataUrl ? a.dataUrl.length : 0), 0);
      if (totalB64 > 40 * 1024 * 1024) {
        msg.textContent = 'Вложения слишком большие суммарно — отправь файлы по одному или сожми'; msg.style.color = '#e0526a'; btn.disabled = false; return;
      }
      msg.textContent = 'Отправляю…';
      try {
        const r = await fetch('/api/feedback', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ kind: f.kind.value, text: f.text.value, attachments }) });
        const d = await r.json();
        if (r.ok) { msg.textContent = `✓ Спасибо! Отправлено${d.attachments ? ` (вложений: ${d.attachments})` : ''}.`; msg.style.color = '#5fbf7a'; f.text.value = ''; f.files.value = ''; const pv = f.querySelector('#fb-previews'); if (pv) pv.innerHTML = '';
          State.myFeedbackCount = (State.myFeedbackCount || 0) + 1; checkAchievements(); }
        else { msg.textContent = d.error || 'Ошибка'; msg.style.color = '#e0526a'; }
      } catch { msg.textContent = 'Ошибка сети'; msg.style.color = '#e0526a'; }
      btn.disabled = false;
    })();
    return;
  }

  // --- Телосложение ---
  if (f.id === 'body-form') {
    e.preventDefault();
    const num = (v) => { const x = parseFloat(v); return isNaN(x) ? null : x; };
    State.settings.body = Object.assign({}, State.settings.body, { height: num(f.height.value), weight: num(f.weight.value), sex: f.sex.value || '' });
    if (f.bodyfat) State.settings.body.bodyfat = num(f.bodyfat.value);
    Store.save('settings', State.settings); toast('🧍 Телосложение обновлено'); render();
    return;
  }

  if (f.classList.contains('wk-add-form')) {
    e.preventDefault(); const title = f.title.value.trim(); if (!title) return;
    const date = f.dataset.date || todayStr();
    State.tasks.push({ id: uid(), title, skillId: f.skillId.value, skillIds: [f.skillId.value], estimateMin: 30, difficulty: 'normal', date, done: false, completedAt: null, xpAwarded: 0, goldAwarded: 0, actualMin: null, startTime: null, createdAt: new Date().toISOString() });
    Store.save('tasks', State.tasks); State.wkAddDate = null; render(); return;
  }

  if (f.id === 'capture-form') {
    e.preventDefault(); const text = f.text.value.trim(); if (!text) return;
    State.inbox.unshift({ id: uid(), kind: 'text', text, file: null, type: null, at: new Date().toISOString() });
    Store.save('inbox', State.inbox); track('capture:text'); f.text.value = ''; toast('📝 В Заметках'); render();
    return;
  }
  if (f.id === 'chat-form') {
    e.preventDefault(); const inp = document.getElementById('chat-input'); sendChat(inp && inp.value);
    return;
  }
  if (f.id === 'party-create') {
    e.preventDefault(); const name = f.name.value.trim(); if (!name) return;
    fetch('/api/party/create', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name }) })
      .then((r) => r.json()).then((d) => { if (d.party) { State.party = d.party; toast('🤝 Пати создана — поделись кодом'); render(); } else toast('Не удалось создать'); }).catch(() => toast('Сетевая ошибка'));
    return;
  }
  if (f.id === 'party-join') {
    e.preventDefault(); const code = f.code.value.trim().toUpperCase(); if (!code) return;
    fetch('/api/party/join', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ code }) })
      .then((r) => r.json()).then((d) => { if (d.party) { State.party = d.party; toast('🤝 Ты в пати!'); render(); } else toast(d.error === 'full' ? 'Пати заполнена' : d.error === 'already_in_party' ? 'Ты уже в пати' : 'Код не найден'); }).catch(() => toast('Сетевая ошибка'));
    return;
  }
  if (f.id === 'add-antihabit') {
    e.preventDefault(); const title = f.title.value.trim(); if (!title) return;
    State.antihabits = State.antihabits || [];
    State.antihabits.push({ id: 'ah_' + uid(), title, approach: (f.approach && f.approach.value) || '', slips: [], createdAt: new Date().toISOString() });
    Store.save('antihabits', State.antihabits); render();
    return;
  }
  if (f.id === 'ai-keys') {
    e.preventDefault();
    const body = {};
    AI_PROVIDERS.forEach((p) => { if (f[p.id] && f[p.id].value.trim()) body[p.id] = f[p.id].value.trim(); });
    if (!Object.keys(body).length) { const m0 = document.getElementById('ai-keys-msg'); if (m0) m0.textContent = 'Вставь хотя бы один ключ'; return; }
    const msg = document.getElementById('ai-keys-msg'); if (msg) msg.textContent = 'Сохраняю…';
    fetch('/api/ai/keys', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
      .then((r) => r.json()).then((d) => { const m = {}; AI_PROVIDERS.forEach((p) => m[p.id] = !!d[p.id]); State.aiKeys = m; toast('🤖 Ключ сохранён'); render(); })
      .catch(() => { if (msg) msg.textContent = 'Ошибка'; });
    return;
  }
  if (f.id === 'add-task') {
    e.preventDefault(); const title = f.title.value.trim(); if (!title) return;
    const tDate = (f.date && f.date.value) || todayStr(); // вкладка «Календарь» добавляет на выбранный день
    State.tasks.push({ id: uid(), title, skillId: f.skillId.value, skillIds: [f.skillId.value], estimateMin: readDurInput(f, 'estimateMin'), difficulty: f.difficulty.value, date: tDate, done: false, completedAt: null, xpAwarded: 0, goldAwarded: 0, actualMin: null, startTime: null, createdAt: new Date().toISOString() });
    Store.save('tasks', State.tasks); render();
  } else if (f.id === 'add-goal') {
    e.preventDefault(); const title = f.title.value.trim(); if (!title) return;
    const type = f.type.value || 'short';
    const xpReward = f.xpReward.value !== '' ? Math.max(0, Number(f.xpReward.value)) : GOAL_XP[type];
    const tgt = (f.mTarget && f.mTarget.value !== '') ? Number(f.mTarget.value) : null;
    let metric = null;
    if (tgt != null && !isNaN(tgt)) {
      const cur = (f.mStart && f.mStart.value !== '') ? Number(f.mStart.value) : 0;
      metric = { start: cur, current: cur, target: tgt, unit: (f.mUnit.value || '').trim().slice(0, 12), lowerBetter: !!(f.mLower && f.mLower.checked), maintain: !!(f.mMaintain && f.mMaintain.checked), everReached: false, log: [] };
    }
    const status = (f.status && f.status.value) || 'active';
    const window = (f.window && f.window.value || '').trim().slice(0, 40);
    const goal = { id: 'g_' + uid(), title, skillId: f.skillId.value, type, xpReward, parentId: f.parentId.value || null, targetDate: f.targetDate.value || null, steps: [], metric, status, window, createdAt: new Date().toISOString(), completedAt: null, archived: false };
    State.goals.push(goal);
    if (goal.metric) refreshGoalCompletion(goal); // вдруг уже достигнута на старте (напр. жим уже взят)
    Store.save('goals', State.goals); render();
  } else if (f.classList.contains('add-step-form')) {
    e.preventDefault(); const g = goalById(f.dataset.goal); const v = f.step.value.trim(); if (!g || !v) return;
    g.steps.push({ id: 's_' + uid(), title: v, done: false }); refreshGoalCompletion(g);
    Store.save('goals', State.goals); render();
  } else if (f.classList.contains('metric-form')) {
    e.preventDefault(); const g = goalById(f.dataset.goal); if (!g || !g.metric || f.val.value === '') return;
    const val = Number(f.val.value); if (isNaN(val)) return;
    g.metric.current = val; g.metric.log = g.metric.log || [];
    g.metric.log.unshift({ date: todayStr(), value: val }); g.metric.log = g.metric.log.slice(0, 50);
    refreshGoalCompletion(g); Store.save('goals', State.goals); checkAchievements(); render(); publishLeaderboard();
  } else if (f.id === 'add-reward') {
    e.preventDefault(); const name = f.name.value.trim(); if (!name) return;
    if (!isPro() && State.rewards.length >= FREE_REWARDS_MAX) { showPaywall('Больше наград'); return; }
    State.rewards.push({ id: 'r_' + uid(), name, icon: f.icon.value.trim() || '🎁', cost: Math.max(1, Number(f.cost.value) || 1), createdAt: new Date().toISOString() });
    Store.save('rewards', State.rewards); render();
  }
}

// Модалка каталога предустановленных наград
function openRewardCatalog() {
  if (document.getElementById('rw-catalog')) return;
  const have = new Set(State.rewards.map((r) => r.name));
  const rows = REWARD_CATALOG.map((c, i) => `<div class="rwc-row">
      <span class="rwc-ic">${c.icon}</span><span class="rwc-name">${esc(c.name)}</span><span class="rwc-cost">🪙 ${c.cost}</span>
      ${have.has(c.name) ? '<span class="muted" style="font-size:12px">добавлено ✓</span>' : `<button class="btn ghost sm" data-action="add-catalog-reward" data-idx="${i}">+ Добавить</button>`}
    </div>`).join('');
  const ov = document.createElement('div'); ov.id = 'rw-catalog'; ov.className = 'modal-overlay';
  ov.innerHTML = `<div class="guide-box"><button class="modal-x" data-action="close-reward-catalog">✕</button>
    <h2>${t('📚 Каталог наград')}</h2>
    <p class="muted">Готовые награды с откалиброванными ценами — как дроп с босса. Добавь свои в форме на странице наград.</p>
    <div class="rwc-list">${rows}</div></div>`;
  document.body.appendChild(ov);
}

// ── Гайд «Тень ведёт тебя» (ONBOARDING-PLAN.md, Фаза 1+2) ──
