    if (!confirm(`Удалить выбранные цели: ${ids.length}?`)) return;
    const s = new Set(ids); State.goals = State.goals.filter((g) => !s.has(g.id)); Store.save('goals', State.goals); toast(`🗑 Удалено: ${ids.length}`); render();
