    if (!node || node.unlocked) return;
    node.unlocked = true; node.claimedAt = new Date().toISOString();
    Store.save('skilltree', State.tree);
    // Фаза 2: «Тень записала в летопись» — теперь буквально (журнал компаньона, как чек-ины)
